function solve(data) {
  const { rewards, values, nextValues, terminated, truncated, gamma, lambda } = data;
  const n = rewards.length;
  const advantages = new Array(n);
  const returns = new Array(n);
  const discount = gamma * lambda;
  let tail = 0;
  for (let t = n - 1; t >= 0; t--) {
    const delta = rewards[t] + (terminated[t] ? 0 : gamma * nextValues[t]) - values[t];
    tail = delta + (terminated[t] || truncated[t] ? 0 : discount * tail);
    advantages[t] = tail;
    returns[t] = tail + values[t];
  }
  return { advantages, returns };
}

function solve(data) {
  var rewards = (data && data.rewards) || [];
