  var nextValues = (data && data.nextValues) || [];
  var terminated = (data && data.terminated) || [];
  var truncated = (data && data.truncated) || [];
  var gamma = Number(data && data.gamma);
  var lambda = Number(data && data.lambda);
  if (!isFinite(gamma)) gamma = 0;
  if (!isFinite(lambda)) lambda = 0;
  var n = rewards.length;
  var advantages = new Array(n);
  var returns = new Array(n);
  var gae = 0;
  for (var t = n - 1; t >= 0; t--) {
    var term = terminated[t] ? 1 : 0;
    var trunc = truncated[t] ? 1 : 0;
    var r = Number(rewards[t]);
    var v = Number(values[t]);
    var nv = Number(nextValues[t]);
    var delta = r + gamma * (1 - term) * nv - v;
    var stop = (term || trunc) ? 1 : 0;
    gae = delta + gamma * lambda * (1 - stop) * gae;
    advantages[t] = gae;
    returns[t] = gae + v;
  }
  return { advantages: advantages, returns: returns };
}

