    if (typeof x === 'string') {
      var s = x.trim().toLowerCase();
      return (s === 'true' || s === '1' || s === 'yes') ? 1 : 0;
    }
    return x ? 1 : 0;
  }
  var n = rewards.length;
  var advantages = new Array(n);
  var returns = new Array(n);
