    var delta = r + gamma * (1 - term) * nv - v;
    var cont = (term || trunc) ? 0 : 1;
    var adv = delta + gamma * lambda * cont * lastGae;
    advantages[t] = adv;
    returns[t] = adv + v;
    lastGae = adv;
  }
